package com.example.bmmoney;
import android.content.*;import android.os.Bundle;import android.text.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.bmmoney.data.*;import com.example.bmmoney.remote.FirebaseSyncManager;import com.google.android.material.button.MaterialButton;
public class AddTransactionActivity extends AppCompatActivity{private EditText edtTitle,edtAmount,edtNote;private Spinner spinnerCategory;private RadioButton radioIncome;private MaterialButton btnSave;private AppDatabase db;private SharedPreferences prefs;private final String[] categories={"Ăn uống","Di chuyển","Mua sắm","Hóa đơn","Nhà cửa","Lương","Giải trí","Sức khỏe","Khác"};@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_add_transaction);ThemeManager.apply(this);db=AppDatabase.getInstance(this);prefs=getSharedPreferences("transaction_draft",MODE_PRIVATE);edtTitle=findViewById(R.id.edtTitle);edtAmount=findViewById(R.id.edtAmount);edtNote=findViewById(R.id.edtNote);spinnerCategory=findViewById(R.id.spinnerCategory);radioIncome=findViewById(R.id.radioIncome);btnSave=findViewById(R.id.btnSave);spinnerCategory.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,categories));restoreDraft();setupDraft();setupNav();btnSave.setOnClickListener(v->save());findViewById(R.id.btnBack).setOnClickListener(v->finish());findViewById(R.id.btnScanReceipt).setOnClickListener(v->Toast.makeText(this,"Tính năng quét hóa đơn sẽ được kết nối sau",Toast.LENGTH_SHORT).show());}private void save(){String title=edtTitle.getText().toString().trim(), amountText=edtAmount.getText().toString().trim();if(title.isEmpty()){edtTitle.setError("Vui lòng nhập mô tả");return;}if(amountText.isEmpty()){edtAmount.setError("Vui lòng nhập số tiền");return;}double amount;try{amount=Double.parseDouble(amountText);}catch(Exception e){edtAmount.setError("Số tiền không hợp lệ");return;}String type=radioIncome.isChecked()?"INCOME":"EXPENSE";TransactionEntity t=new TransactionEntity(title,amount,type,spinnerCategory.getSelectedItem().toString(),edtNote.getText().toString().trim(),System.currentTimeMillis());long id=db.transactionDao().insert(t);t.setId((int)id);new FirebaseSyncManager(this).uploadTransaction(t);prefs.edit().clear().apply();Toast.makeText(this,"Đã lưu giao dịch",Toast.LENGTH_SHORT).show();startActivity(new Intent(this,MainActivity.class));finish();}private void restoreDraft(){edtTitle.setText(prefs.getString("title",""));edtAmount.setText(prefs.getString("amount",""));edtNote.setText(prefs.getString("note",""));radioIncome.setChecked(prefs.getBoolean("income",false));}private void setupDraft(){TextWatcher w=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int st,int b,int c){prefs.edit().putString("title",edtTitle.getText().toString()).putString("amount",edtAmount.getText().toString()).putString("note",edtNote.getText().toString()).putBoolean("income",radioIncome.isChecked()).apply();}};edtTitle.addTextChangedListener(w);edtAmount.addTextChangedListener(w);edtNote.addTextChangedListener(w);}private void setupNav(){findViewById(R.id.navHome).setOnClickListener(v->startActivity(new Intent(this,MainActivity.class)));findViewById(R.id.navAdd).setOnClickListener(v->{});findViewById(R.id.navReport).setOnClickListener(v->startActivity(new Intent(this,ReportActivity.class)));findViewById(R.id.navSearch).setOnClickListener(v->startActivity(new Intent(this,SearchActivity.class)));findViewById(R.id.navSettings).setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));}}
